Here's a possible implementation of the function you described:

```cpp
#include <string>

std::string convertMarkdownToHTML(const std::string& markdownInput) {
    std::string htmlOutput;

    // Replace markdown formatting with HTML equivalents
    // Note: This is just a basic example, and there are many cases where the same formatting can be achieved using different Markdown and/or HTML constructs.

    // Headers
    size_t spacePos = markdownInput.find(' ');
    if (markdownInput.front() == '#' && spacePos != std::string::npos) {
        std::string headerRank = markdownInput.substr(1, 1);
        if (headerRank == "1") {
            htmlOutput = "<h1>" + markdownInput.substr(spacePos + 1) + "</h1>";
        }
        else {
            htmlOutput = "<h" + headerRank + ">" + markdownInput.substr(spacePos + 1) + "</h>";
        }
    }
    else {
        htmlOutput = "<p>" + markdownInput + "</p>";
    }

    // Emphasis
    size_t firstItalicPos = markdownInput.find('_');
    size_t firstBoldPos = markdownInput.find(**_bold_iter);
    if (firstItalicPos != std::string::npos || firstBoldPos != std::string::npos) {
        std::string emphasizedText;
        if (firstItalicPos != std::string::npos) {
            emphasizedText += markdownInput.substr(firstItalicPos, firstItalicPos + 1 == markdownInput.size() ? 0 : 1);
            emphasizedText += "_";
            htmlOutput = "<em>" + emphasizedText + "</em>";
            if (firstBoldPos != std::string::npos) {
                return "<strong>" + emphasizedText + "</strong>";
            }
        }
        else if (firstBoldPos != std::string::npos) {
            htmlOutput = "<strong>" + markdownInput.substr(firstBoldPos, markdownInput.size()) + "</strong>";
