```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int countWordInFile(const string& word, const string& filename) {
    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error al abrir el archivo: " << filename << endl;
        return -1;
    }

    string currentWord;
    int count = 0;
    while (file >> currentWord) {
        if (currentWord == word) {
            count++;
        }
    }

    file.close();
    return count;
}

